package com.hushtv.tv.data

import com.hushtv.tv.R

/**
 * v1.44.138-dev — Stable id ↔ drawable mapping for the 36 profile
 * avatars generated by /app/_buildenv/generate-avatars.py and baked
 * into app/src/dev/res/drawable-nodpi/avatar_*.webp.
 *
 * Why a hand-typed map vs reflection on R.drawable
 * ────────────────────────────────────────────────
 * R8 minification would erase any reflectively-resolved drawable
 * names. Listing the resource ids explicitly forces the compiler
 * to keep them in the symbol table forever. Adding a new avatar
 * = regenerate via the Python script + add one line here.
 *
 * Layout convention
 * ─────────────────
 * Humans use the `h##` prefix, animals use `a##`. The picker grid
 * uses the suffix label (after the underscore) as a one-word a11y
 * description ("Alex", "Fox", etc.) so screen readers and the
 * profile-edit form have something useful to say.
 *
 * Flavor scoping
 * ──────────────
 * The drawables live ONLY under app/src/dev/res/drawable-nodpi/, so
 * canada / official builds will fail to compile if they try to
 * reference R.drawable.avatar_*. That's a feature — it forces us
 * to keep all profile-system code paths off canada until the
 * promotion green light. Any UI that calls AvatarCatalog.find()
 * is also gated behind ActiveProfile.isActive.
 */
data class HushAvatar(
    val id: String,           // "h01_alex"
    val drawableRes: Int,     // R.drawable.avatar_h01_alex
    val label: String,        // "Alex"  — friendly name for a11y / picker
    val kind: Kind,
) {
    enum class Kind { HUMAN, ANIMAL }
}

