    /** All 36 avatars in canonical order — humans first, animals
     *  second. Picker grids iterate this directly. */
    fun all(): List<HushAvatar> = entries

    /** Subsets for the picker filter tabs ("Humans" / "Animals"). */
    fun humans(): List<HushAvatar> = entries.filter { it.kind == HushAvatar.Kind.HUMAN }
    fun animals(): List<HushAvatar> = entries.filter { it.kind == HushAvatar.Kind.ANIMAL }

    /** Lookup by id. Returns null when the id is stale (e.g. a
     *  synced profile points at an avatar we've since removed) —
     *  callers should fall back to [defaultAvatar]. */
    fun find(id: String): HushAvatar? = entries.firstOrNull { it.id == id }

    /** Safe fallback for any missing avatar. Picks a friendly,
     *  gender-neutral avatar so the placeholder doesn't feel
     *  like an error state. */
    fun defaultAvatar(): HushAvatar = entries.first()  // h01_alex
